<?php

use App\Actions\Finance\DeleteFinancialEntry;
use App\Enums\EntryStatus;
use App\Enums\EntryType;
use App\Models\FinancialCategory;
use App\Models\FinancialEntry;
use App\Queries\FinancialEntriesQuery;
use Illuminate\Contracts\View\View;
use Illuminate\Validation\ValidationException;
use Livewire\Attributes\On;
use Livewire\Attributes\Url;
use Livewire\Component;
use Livewire\WithPagination;

/**
 * Financial entries (US-10.1, US-10.4): paginated table filtered by type,
 * category, status and period (due or payment date), all kept in the URL.
 * Entries generated by payments show a lock and a link to the holder, with no
 * actions. Requires `finance.view`; editing, deleting and settling manual
 * entries require `finance.manage` (and the entry policy).
 */
new class extends Component
{
    use WithPagination;

    #[Url]
    public string $type = '';

    #[Url]
    public string $category = '';

    #[Url]
    public string $status = '';

    #[Url(as: 'period_by')]
    public string $periodBy = FinancialEntriesQuery::PeriodByDueDate;

    #[Url]
    public string $from = '';

    #[Url]
    public string $until = '';

    public function mount(): void
    {
        $this->authorize('finance.view');
    }

    /**
     * Changing the type clears a category of the other type. Any filter
     * change goes back to the first page.
     */
    public function updated(string $property): void
    {
        if ($property === 'type') {
            $this->category = '';
        }

        if (in_array($property, ['type', 'category', 'status', 'periodBy', 'from', 'until'], true)) {
            $this->resetPage();
        }
    }

    public function clearFilters(): void
    {
        $this->reset('type', 'category', 'status', 'periodBy', 'from', 'until');
        $this->resetPage();
    }

    public function delete(int $id, DeleteFinancialEntry $deleteEntry): void
    {
        $this->authorize('finance.manage');

        $entry = FinancialEntry::findOrFail($id);
        $this->authorize('delete', $entry);

        try {
            $deleteEntry->handle($entry);
        } catch (ValidationException $exception) {
            $this->dispatch('notify', type: 'error', title: $exception->getMessage());

            return;
        }

        $this->dispatch('notify', title: 'Lançamento excluído', description: $entry->description);
    }

    /**
     * Render again after an entry is saved or settled in the modals.
     */
    #[On('financial-entry-saved')]
    public function refreshEntries(): void {}

    protected function entriesQuery(): FinancialEntriesQuery
    {
        return new FinancialEntriesQuery(
            type: EntryType::tryFrom($this->type),
            categoryId: ctype_digit($this->category) ? (int) $this->category : null,
            status: EntryStatus::tryFrom($this->status),
            periodBy: $this->periodBy === FinancialEntriesQuery::PeriodByPaymentDate ? FinancialEntriesQuery::PeriodByPaymentDate : FinancialEntriesQuery::PeriodByDueDate,
            from: $this->from ?: null,
            until: $this->until ?: null,
        );
    }

    public function render(): View
    {
        $type = EntryType::tryFrom($this->type);

        return $this->view([
            'entries' => $this->entriesQuery()->ordered()->paginate(20),
            'typeFilters' => ['' => 'Todos', EntryType::Income->value => 'Receitas', EntryType::Expense->value => 'Despesas'],
            'statusFilters' => ['' => 'Todos', ...collect(EntryStatus::cases())->mapWithKeys(fn (EntryStatus $status): array => [$status->value => $status->label()])->all()],
            'categoryOptions' => FinancialCategory::query()
                ->when($type, fn ($query, EntryType $type) => $query->ofType($type))
                ->orderBy('name')
                ->pluck('name', 'id')
                ->all(),
            'canManage' => auth()->user()->can('finance.manage'),
        ]);
    }
};
?>

